-- Study Abroad country content, BATCH 15: Nepal, Bangladesh, Sri Lanka, Pakistan, Mauritius.
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('nepal', 'bangladesh', 'sri-lanka', 'pakistan', 'mauritius'));
UPDATE countries SET why_title = 'Why study in Nepal?', why_body = '<p>Nepal is a low-cost study destination, popular with students from South Asia for medicine (MBBS and BDS), nursing and engineering, with many English-medium programmes.</p><ul><li>English-medium MBBS and BDS at recognised medical colleges</li><li>Lower fees for SAARC students</li><li>Cultural and geographic proximity to India</li><li>Kathmandu University is a leading private university</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Foreign students generally need a <strong>student visa</strong> from the Department of Immigration of Nepal or a Nepalese mission. This search found no official 2026 visa rules, so confirm them with the embassy.</p><ul><li>Admission letter and proof of fee payment from the college</li><li>Valid passport (some listings ask for at least one year of validity)</li><li>Passport photographs and medical certificate</li><li>Indian students also need NEET qualification under Indian rules for medical study abroad</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Nepal Department of Immigration and your college site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each college. Kathmandu University''s 2026 MBBS seats were filled entirely by international students, so apply early.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof</li><li>Entrance exam: NEET for Indian MBBS applicants; college tests for others</li><li>Passport copy and photographs</li><li>Medical fitness certificate</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Nepal offers no MBBS scholarships to foreign students, and fees differ by nationality.</p><ul><li>SAARC students pay lower fees than other nationalities</li><li>Example: KIST Medical College lists INR 6,350,000 for the 2026-27 international MBBS course, in three instalments including hostel and mess</li><li>Kathmandu Medical College lists a one-time admission fee of INR 300,000 plus other charges (2025/26)</li><li>Check each college; agent pages give inconsistent totals</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official college site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> Class 12 with physics, chemistry and biology for medicine</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof for English-medium programmes</li></ul>' WHERE slug = 'nepal';
UPDATE countries SET why_title = 'Why study in Bangladesh?', why_body = '<p>Bangladesh offers low-cost study, with English-medium MBBS and BDS at government and private medical colleges and strong engineering programmes at BUET.</p><ul><li>English-medium MBBS at recognised medical colleges</li><li>Low tuition and living costs</li><li>Government seats reserved for foreign students</li><li>Close ties with South Asian students</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>Every foreign student needs a <strong>student visa</strong> from a Bangladesh mission before travel, and it must be renewed annually while studying.</p><ul><li>Admission letter from the college or university</li><li>Passport and photographs</li><li>Indian citizens pay no visa fee but a service charge of about INR 800 is reported</li><li>Annual visa renewal while studying</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Bangladesh High Commission and your college site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>For 2025-26 the government reserved 224 MBBS and BDS seats in its colleges for foreign students. Private colleges admit directly.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof</li><li>NEET qualification for Indian medical applicants</li><li>Application to the university or the Ministry of Education for government seats</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Estimates vary widely.</p><ul><li>Dhaka University: US$500 a year for SAARC citizens and US$1,200 for others, plus department fees</li><li>MBBS: tuition from US$6,600 to US$10,000 (one source), total costs from INR 28 lakh to 45 lakh over six years (another); treat as indicative</li><li>Living costs: about US$150-$300 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official college site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> Class 12 with physics, chemistry and biology for medicine; Dhaka University asks for GPA 3.5 for local applicants</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof for English-medium programmes</li></ul>' WHERE slug = 'bangladesh';
UPDATE countries SET why_title = 'Why study in Sri Lanka?', why_body = '<p>Sri Lanka offers English-medium degrees at lower costs than many destinations, with established public universities and growing private options in business, IT and medicine.</p><ul><li>English-medium private and public programmes</li><li>Low cost compared with many destinations</li><li>Strong tourism, IT and business sectors</li><li>Close to South India</li></ul>', visa_title = 'Visa requirements', visa_body = '<p>Get an <strong>entry visa</strong> before arriving, then a <strong>residence visa (Education)</strong> within 30 days of arrival. The University of Colombo advises allowing about three months. Tourist visas are not converted to student visas.</p><ul><li>Admission letter and proof of funds</li><li>Passport and photographs</li><li>Visa fee: sources conflict (USD 50, USD 200 and LKR 100), so check with the Department of Immigration and Emigration</li><li>The Department lists no work rights for students</li><li>Some exchange students are exempt from tuition</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Sri Lanka Department of Immigration and Emigration and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Foreign students apply through the University Grants Commission (UGC) for state universities, or directly to private institutions.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof</li><li>Application through UGC foreign-student admission handbook</li><li>Entrance requirements for medicine</li><li>Passport copy and photographs</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Fees for foreign-qualified students are set by the UGC.</p><ul><li>Guide range: from US$3,000 (arts and humanities) to US$15,000 (medicine and dentistry) a year (2025/26)</li><li>University of Colombo international Master''s: from LKR 125,000 to LKR 869,100 (guide)</li><li>Living costs: about US$300-$600 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> A-levels or an equivalent with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof for English-medium programmes</li></ul>' WHERE slug = 'sri-lanka';
UPDATE countries SET why_title = 'Why study in Pakistan?', why_body = '<p>Pakistan offers low-cost degrees at established universities such as LUMS, NUST and Habib University, with English-medium instruction in many programmes.</p><ul><li>English-medium programmes at leading universities</li><li>Low tuition and living costs</li><li>Strong in engineering, computing and medicine</li><li>Large student community</li></ul>', visa_title = 'Student visa requirements', visa_body = '<p>The Ministry of Interior issues a <strong>Student Visa</strong> valid up to 2 years for higher education, applied for through the Pakistan Online Visa System. It must be renewed during study.</p><ul><li>Admission letter from a Ministry-recognised institution</li><li>Passport and photographs</li><li>Allow about three months for processing (reported)</li><li>An NOC from your government may be requested (unverified)</li><li>IBCC equivalency certificate needed by some international students</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Pakistan Ministry of Interior and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university. LUMS, NUST and others have their own admission tests.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof</li><li>SAT, NET or university admission test</li><li>Motivation letter for postgraduate programmes</li><li>IBCC equivalency certificate for school qualifications</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Tuition figures for LUMS and NUST were not found.</p><ul><li>Habib University: same fee structure for international students and residents, with no additional charges</li><li>Check each university''s fee page</li><li>Living costs: about US$150-$350 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with equivalency</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof for English-medium programmes</li></ul>' WHERE slug = 'pakistan';
UPDATE countries SET why_title = 'Why study in Mauritius?', why_body = '<p>Mauritius is a stable island nation with English and French as working languages, a growing higher education sector and international branch campuses, plus strong tourism and finance sectors.</p><ul><li>English-medium degrees at the University of Mauritius and others</li><li>Stable democracy with a growing economy</li><li>Strong tourism, finance and ocean economy sectors</li><li>Work allowed for students (up to 20 hours reported)</li></ul>', visa_title = 'Student permit requirements', visa_body = '<p>The university helps with a <strong>provisional visa (3 months)</strong>, then students apply for a <strong>Student Residence Permit</strong> from the Passport and Immigration Office after arrival. Tourist, business or social visas cannot be switched to a study permit.</p><ul><li>Signed Application to Enter Mauritius form and photographs</li><li>Fees must be paid before the student visa is issued</li><li>Do not travel before the entry permit is issued</li><li>Medical tests (HIV, Hepatitis B, chest X-ray) after arrival</li><li>Renew the permit two to three months before expiry</li><li>Full-time students may work up to 20 hours a week (reported)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Passport and Immigration Office and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each institution through its application portal.</p><ul><li>Academic transcripts and certificates</li><li>English proficiency proof</li><li>Motivation letter for postgraduate programmes</li><li>Passport copy and photographs</li><li>Entry permit documentation</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Sources disagree on fees.</p><ul><li>University of Mauritius block fee (2026-27, via StudyCountry): US$6,000 a year for science and technology and US$5,000 for other programmes, with a 50% scholarship for international undergraduates (reported)</li><li>Another guide gives US$2,500-$4,000 a year; confirm on the university site</li><li>Living costs: about US$500-$900 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate with required subjects</li><li><strong>Master''s:</strong> a relevant bachelor''s degree</li><li><strong>Language:</strong> English proof for English-medium programmes</li></ul>' WHERE slug = 'mauritius';
COMMIT;
